<?php
require_once __DIR__.'/../../config/bootstrap.php'; require_internal(); $pdo=db(); $pageTitle='PDV';
if(isset($_GET['from_encomenda'])){
    $eid=(int)$_GET['from_encomenda'];$st=$pdo->prepare('SELECT * FROM encomendas WHERE id=?');$st->execute([$eid]);$en=$st->fetch();
    if($en){$it=$pdo->prepare('SELECT ei.*,p.nome FROM encomenda_itens ei JOIN produtos p ON p.id=ei.produto_id WHERE ei.encomenda_id=?');$it->execute([$eid]);$_SESSION['pdv']=['cliente_id'=>(int)$en['cliente_id'],'desconto'=>(float)$en['desconto'],'encomenda_id'=>(int)$en['id'],'items'=>array_map(fn($x)=>['id'=>(int)$x['produto_id'],'nome'=>$x['nome'],'qty'=>(float)$x['quantidade'],'preco'=>(float)$x['preco_unitario']],$it->fetchAll())];}
    redirect('index.php');
}
$cart=$_SESSION['pdv']??['cliente_id'=>0,'desconto'=>0,'encomenda_id'=>0,'items'=>[]];
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=$_POST['action']??'';
 if($action==='clear'){unset($_SESSION['pdv']);redirect('index.php');}
 if($action==='add'){$pid=(int)$_POST['produto_id'];$st=$pdo->prepare('SELECT id,nome,preco,estoque FROM produtos WHERE id=? AND ativo=1');$st->execute([$pid]);$p=$st->fetch();if($p){$found=false;foreach($cart['items'] as &$i){if($i['id']===$p['id']){$i['qty']++;$found=true;break;}}unset($i);if(!$found)$cart['items'][]=['id'=>(int)$p['id'],'nome'=>$p['nome'],'qty'=>1,'preco'=>(float)$p['preco']];$_SESSION['pdv']=$cart;}redirect('index.php');}
 if($action==='qty'){$pid=(int)$_POST['produto_id'];$q=max(.01,(float)$_POST['qty']);foreach($cart['items'] as &$i)if($i['id']===$pid)$i['qty']=$q;unset($i);$_SESSION['pdv']=$cart;redirect('index.php');}
 if($action==='remove'){$pid=(int)$_POST['produto_id'];$cart['items']=array_values(array_filter($cart['items'],fn($i)=>$i['id']!==$pid));$_SESSION['pdv']=$cart;redirect('index.php');}
 if($action==='set_discount'){$cart['desconto']=max(0,number_value($_POST['desconto']??0));$_SESSION['pdv']=$cart;redirect('index.php');}
 if($action==='set_customer'){$cart['cliente_id']=(int)$_POST['cliente_id'];$_SESSION['pdv']=$cart;redirect('index.php');}
 if($action==='finalizar'){
   $method=$_POST['forma_pagamento']??'Dinheiro';$install=(int)($_POST['parcelas']??1);$received=number_value($_POST['valor_recebido']??0);$sub=0;
   foreach($cart['items'] as $i){$st=$pdo->prepare('SELECT * FROM produtos WHERE id=? AND ativo=1');$st->execute([$i['id']]);$p=$st->fetch();if(!$p){flash('danger','Produto não encontrado.');redirect('index.php');}if((float)$p['estoque']<(float)$i['qty']){flash('danger','Estoque insuficiente para '.$p['nome'].'.');redirect('index.php');}$sub+=(float)$i['qty']*(float)$i['preco'];}
   $disc=min($sub,max(0,(float)$cart['desconto']));$total=max(0,$sub-$disc);if($method==='Dinheiro'&&$received+0.00001<$total){flash('danger','Valor recebido insuficiente.');redirect('index.php');}if($method==='Crédito')$install=min(12,max(1,$install));else$install=1;$change=$method==='Dinheiro'?max(0,$received-$total):0;$cash=open_cash();if(!$cash){flash('danger','Abra o caixa antes de finalizar a venda.');redirect('index.php');}
   $pdo->beginTransaction();try{
     $num=next_number('VEN','vendas');$pdo->prepare('INSERT INTO vendas(numero,cliente_id,usuario_id,data_venda,subtotal,desconto,total,forma_pagamento,parcelas,valor_recebido,troco,status,origem_encomenda_id,observacoes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$num,$cart['cliente_id']?:null,current_user()['id'],now(),$sub,$disc,$total,$method,$install,$received,$change,'Concluida',$cart['encomenda_id']?:null,'']);$vid=(int)$pdo->lastInsertId();
     $itemSt=$pdo->prepare('INSERT INTO venda_itens(venda_id,produto_id,quantidade,preco_unitario,subtotal) VALUES(?,?,?,?,?)');foreach($cart['items'] as $i){$itemSt->execute([$vid,$i['id'],$i['qty'],$i['preco'],$i['qty']*$i['preco']]);stock_move((int)$i['id'],-(float)$i['qty'],'Venda','vendas',$vid,current_user()['id'],'Venda '.$num);}
     add_cash_movement((int)$cash['id'],$method,$total,'Venda '.$num,current_user()['id'],$vid);
     if($method==='Crédito'){ $base=round($total/$install,2);$remain=$total;for($n=1;$n<=$install;$n++){ $v=$n===$install?round($remain,2):$base;$remain-=$v;$due=date('Y-m-d',strtotime('+'.($n*30).' days'));$pdo->prepare("INSERT INTO movimentacoes_financeiras(tipo,categoria,descricao,valor,vencimento,status,usuario_id,origem,referencia_id,criado_em) VALUES('Entrada','Cartão de crédito',?,?,?,?,?,?,?,?)")->execute(['Venda '.$num.' — parcela '.$n.'/'.$install,$v,$due,'Pendente',current_user()['id'],'venda',$vid,now()]); }}
     else {$pdo->prepare("INSERT INTO movimentacoes_financeiras(tipo,categoria,descricao,valor,vencimento,data_pagamento,status,usuario_id,origem,referencia_id,criado_em) VALUES('Entrada','Vendas',?,?,?,?,?,?,?,?,?)")->execute(['Venda '.$num,$total,today(),today(),'Pago',current_user()['id'],'venda',$vid,now()]);}
     if(!empty($cart['encomenda_id'])){$pdo->prepare("UPDATE encomendas SET status='Entregue' WHERE id=?")->execute([$cart['encomenda_id']]);$pdo->prepare('INSERT INTO encomenda_status_historico(encomenda_id,status_anterior,status_novo,usuario_id,data_hora) VALUES(?,?,?,?,?)')->execute([$cart['encomenda_id'],'Em preparação','Entregue',current_user()['id'],now()]);}
     $pdo->commit();log_action('venda','vendas',$vid,'Venda '.$num);unset($_SESSION['pdv']);redirect('comprovante.php?id='.$vid);
   }catch(Throwable $e){$pdo->rollBack();flash('danger','Não foi possível concluir a venda.');redirect('index.php');}
 }
}
$q=trim($_GET['q']??'');$products=[];if($q!==''){$st=$pdo->prepare('SELECT id,nome,preco,estoque,codigo,codigo_barras FROM produtos WHERE ativo=1 AND (nome LIKE ? OR codigo LIKE ? OR codigo_barras LIKE ?) ORDER BY nome LIMIT 40');$x="%$q%";$st->execute([$x,$x,$x]);$products=$st->fetchAll();}
$clients=$pdo->query('SELECT id,nome FROM clientes WHERE ativo=1 ORDER BY nome')->fetchAll();$subtotal=0;foreach($cart['items'] as $i)$subtotal+=$i['qty']*$i['preco'];$discount=min($subtotal,$cart['desconto']);$total=$subtotal-$discount;
include __DIR__.'/../../includes/header.php'; ?>
<div class="page-head"><div><h1>PDV</h1><div class="muted">Leitor USB pode preencher o campo de pesquisa como teclado.</div></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="clear"><button class="btn secondary" onclick="return confirmAction('Limpar a venda atual?')">Limpar</button></form></div>
<div class="pdv-layout"><div><div class="card"><form class="search-row"><input autofocus name="q" value="<?=e($q)?>" placeholder="Nome, código interno ou código de barras"><button class="btn primary">Pesquisar</button></form></div><div class="card" style="margin-top:16px"><h3>Produtos</h3><div class="product-picker"><?php foreach($products as $p): ?><form method="post" class="product-card"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="produto_id" value="<?=$p['id']?>"><div class="pname"><?=e($p['nome'])?></div><div class="muted"><?=e($p['codigo'])?> · estoque <?=e($p['estoque'])?></div><div class="price" style="margin:8px 0"><?=money($p['preco'])?></div><button class="btn small primary" <?=$p['estoque']<=0?'disabled':''?>>Adicionar</button></form><?php endforeach;if(!$products): ?><div class="empty" style="grid-column:1/-1">Pesquise para adicionar produtos.</div><?php endif;?></div></div></div>
<div class="card cart"><h3>Carrinho</h3><div class="field"><label>Cliente</label><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="set_customer"><select name="cliente_id" onchange="this.form.submit()"><option value="0">Consumidor não identificado</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>" <?=((int)$cart['cliente_id']===$c['id'])?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select></form></div><div class="cart-items" style="margin-top:13px"><?php foreach($cart['items'] as $i): ?><div class="cart-item"><div><strong><?=e($i['nome'])?></strong><div class="muted"><?=money($i['preco'])?> un.</div></div><div class="text-right"><form class="qty-control" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="produto_id" value="<?=$i['id']?>"><input style="width:72px" class="input" type="number" min=".01" step=".01" name="qty" value="<?=e($i['qty'])?>"><button title="Atualizar">↻</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="produto_id" value="<?=$i['id']?>"><button class="btn small secondary">Remover</button></form><strong><?=money($i['qty']*$i['preco'])?></strong></div></div><?php endforeach;if(!$cart['items']): ?><div class="empty">Carrinho vazio.</div><?php endif; ?></div><div class="total-line"><span>Subtotal</span><strong><?=money($subtotal)?></strong></div><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="set_discount"><label style="flex:1">Desconto <input class="input" type="number" step="0.01" min="0" name="desconto" value="<?=e($discount)?>"></label><button class="btn secondary">Aplicar</button></form><div class="total-line"><span>Desconto</span><strong><?=money($discount)?></strong></div><div class="total-line total"><span>Total</span><strong><?=money($total)?></strong></div><form method="post" style="margin-top:12px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="finalizar"><div class="form-grid"><div class="field col-6"><label>Pagamento</label><select name="forma_pagamento" id="forma" onchange="document.getElementById('credit').style.display=this.value==='Crédito'?'block':'none';document.getElementById('received').style.display=this.value==='Dinheiro'?'block':'none'"><option>Dinheiro</option><option>PIX</option><option>Débito</option><option>Crédito</option></select></div><div class="field col-6" id="credit" style="display:none"><label>Parcelas</label><select name="parcelas"><?php for($i=1;$i<=12;$i++): ?><option value="<?=$i?>"><?=$i?>x</option><?php endfor; ?></select></div><div class="field col-12" id="received"><label>Valor recebido</label><input type="number" min="0" step="0.01" name="valor_recebido" value="<?=number_format($total,2,'.','')?>"></div></div><button class="btn primary w100" <?=$cart['items']?'':'disabled'?>>Finalizar venda</button></form></div></div>
<?php include __DIR__.'/../../includes/footer.php'; ?>
